import java.io.*;

public class E {
    private static boolean isWhitespace(int c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
    }

    private static String nextToken() throws IOException {
        int c;
        while ((c = System.in.read()) != -1 && isWhitespace(c)) {
            // skip
        }
        if (c == -1) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        while (c != -1 && !isWhitespace(c)) {
            sb.append((char) c);
            c = System.in.read();
        }
        return sb.toString();
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private static long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[3];
        long[] b = new long[3];

        for (int i = 0; i < 3; i++) a[i] = nextLong();
        for (int i = 0; i < 3; i++) b[i] = nextLong();

        long max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        long min = Math.max(0, a[0] + b[1] - n)
                 + Math.max(0, a[1] + b[2] - n)
                 + Math.max(0, a[2] + b[0] - n);

        System.out.println(min + " " + max);
    }
}
